"""Static Reward Integrity Leaderboard -> site/ (no framework, no external assets)"""
import json, html, os
d=json.load(open('results/findings_v2.json')); os.makedirs('site/b',exist_ok=True)
e=html.escape
CSS="""body{font:15px/1.5 system-ui,sans-serif;max-width:1100px;margin:auto;padding:24px;color:#111}h1{margin-bottom:0}.sub{color:#555}
table{border-collapse:collapse;width:100%;margin:16px 0}td,th{border-bottom:1px solid #ddd;padding:6px 8px;text-align:left;vertical-align:top}
th{background:#f4f4f4}.b{padding:2px 6px;border-radius:4px;font-size:12px;white-space:nowrap}.v{background:#fde2e1;color:#900}.s{background:#fff4d6;color:#7a5b00}.r{background:#e3ecff;color:#123d99}
code,pre{font:12px ui-monospace,monospace}pre{background:#f7f7f7;padding:8px;overflow:auto;max-height:260px}.draft{background:#111;color:#fff;padding:6px 10px;border-radius:4px;display:inline-block}a{color:#0b57d0}"""
def page(title,body): return f"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>{e(title)}</title><style>{CSS}</style><p class=draft>PREVIEW — not published</p>{body}<hr><p class=sub>Shuna · Reward Integrity Leaderboard · generated {d['generated']} · <a href='/method.html'>method & false-positive policy</a></p>"
rows=sorted(d['benchmarks'],key=lambda x:-x['verified']/x['n_tasks'])
t="".join(f"<tr><td><a href='/b/{x['id']}.html'>{e(x['name'])}</a></td><td>{x['n_tasks']}</td><td><b>{100*x['verified']/x['n_tasks']:.1f}%</b> ({x['verified']})</td><td>{x['helper_only']}</td><td>{x['suspected']}</td><td>{x['rejected']}</td><td>{x['rejects_correct']}</td><td class=sub>{e(x['prior_work'])}</td></tr>" for x in rows)
open('site/index.html','w').write(page('Reward Integrity Leaderboard',f"<h1>Reward Integrity Leaderboard</h1><p class=sub>How often does a benchmark give full marks to a provably wrong solution?</p><table><tr><th>Benchmark</th><th>Tasks</th><th>Confirmed accepts-wrong</th><th>Helper-only</th><th>Suspected</th><th>Rejected by debate</th><th>Rejects correct</th><th>Prior work</th></tr>{t}</table><p class=sub>Confirmed = a wrong program passes every official test, survives the prosecutor/defender debate check (reference sanity, input domain, task wording, harmless-difference, final-answer check), AND is independently confirmed by EvalPlus' validated inputs or documented manual review. Helper-only, suspected and rejected items are not counted.</p>"))
B={'confirmed':('v','confirmed'),'helper-only':('s','helper-only'),'rejected':('r','rejected'),'suspected':('s','suspected'),'rejects-correct-solution':('r','rejects correct')}
for x in d['benchmarks']:
    order={'confirmed':0,'rejects-correct-solution':1,'helper-only':2,'suspected':3,'rejected':4}
    r=""
    for i in sorted(x['items'],key=lambda i:(order[i['status']],i['task_id'])):
        c,l=B[i['status']]
        ev=f"<pre>{e(i.get('diff',''))}</pre><p>Witness input <code>{e(i.get('witness_input',''))}</code> → correct <code>{e(str(i.get('correct','')))}</code>, wrong solution <code>{e(str(i.get('wrong_solution_output','')))}</code></p>" if 'diff' in i else f"<pre>{e(json.dumps(i.get('evidence'),indent=1))}</pre>"
        r+=f"<tr><td>{e(i['task_id'])}</td><td><span class='b {c}'>{l}</span></td><td>{e(i['note'])}<details><summary>evidence</summary>{ev}</details></td></tr>"
    open(f"site/b/{x['id']}.html",'w').write(page(x['name'],f"<p><a href='/'>← leaderboard</a></p><h1>{e(x['name'])}</h1><p>{x['n_tasks']} tasks · <b>{x['confirmed']} confirmed</b> · {x['helper_only']} helper-only · {x['suspected']} suspected · {x['rejected']} rejected · {x['rejects_correct']} reject a correct solution</p><p class=sub>{e(x['prior_work'])}</p><table><tr><th>Task</th><th>Status</th><th>Finding</th></tr>{r}</table>"))
open('site/method.html','w').write(page('Method',"""<h1>Method</h1><ol><li>Make up to 80 small mutants of each reference solution (flip comparisons, arithmetic, and/or, ±1 on integer constants, drop <code>not</code>).</li><li>Keep mutants that pass every official test (for EvalPlus: match the reference on all ~1000 base+plus inputs).</li><li>Fuzz: perturb official test inputs and find one where mutant and reference differ (a <i>witness</i>).</li><li>Confirm independently: re-run the mutant's version of the original function on EvalPlus' validated, contract-respecting inputs. Disagreement = <b>verified · oracle</b>. Where no oracle exists, a documented spec review = <b>verified · review</b>.</li></ol><h2>Debate check</h2><p>Before anything is confirmed, a prosecutor pass re-runs the evidence and a defender pass tries to refute it: D1 the reference passes and is deterministic; D2 the witness input looks like the official inputs (types, value ranges, characters, lengths); D3 the task wording (positive, sorted, distinct, non-empty…) is not violated; D4 the difference is not just a timeout or float noise; D5 for Pro tasks the final answer, not only the helper, is wrong. The prosecutor gets one retry with a conservative fuzz drawn from official inputs. Survivors still need an independent oracle or manual review.</p><h2>False-positive policy</h2><ul><li>Suspected items are never counted.</li><li>Verified-review relies on our reading of the spec and on the reference being correct.</li><li>This measures test strength. It does not show that any model actually exploited a gap.</li><li>Maintainers can dispute any item. Disputed items stay listed with their status.</li></ul><p>Code, data hashes and a one-command re-run are in the repo (link added at publication).</p>"""))
print('site built:',len(os.listdir('site/b')),'benchmark pages')
